scene.background = new THREE.Color(0x020208);

const ambient = new THREE.AmbientLight(0x4040ff, 0.6);
scene.add(ambient);

const keyLight = new THREE.DirectionalLight(0xffffff, 2.0);
keyLight.position.set(4, 6, 4);
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0x8888ff, 0.8);
fillLight.position.set(-4, 2, 4);
scene.add(fillLight);

const gapLight = new THREE.PointLight(0xffaa00, 1.0, 5);
gapLight.position.set(0, 0, 0.5);
scene.add(gapLight);

camera.position.set(0, 0.6, 5.5);
camera.lookAt(0, 0, 0);

const plateGeom = new THREE.BoxGeometry(0.2, 2.4, 2.4);
const plateMat = new THREE.MeshPhysicalMaterial({
  color: 0xffd700,
  metalness: 1.0,
  roughness: 0.12,
  clearcoat: 1.0,
  clearcoatRoughness: 0.1
});

const plate1 = new THREE.Mesh(plateGeom, plateMat);
const plate2 = new THREE.Mesh(plateGeom, plateMat);
scene.add(plate1, plate2);

const arrow1 = new THREE.ArrowHelper(
  new THREE.Vector3(1, 0, 0),
  new THREE.Vector3(0, 0, 0),
  0.45,
  0xff2222,
  0.12,
  0.06
);
arrow1.position.set(0.12, 0, 0);
plate1.add(arrow1);

const arrow2 = new THREE.ArrowHelper(
  new THREE.Vector3(-1, 0, 0),
  new THREE.Vector3(0, 0, 0),
  0.45,
  0xff2222,
  0.12,
  0.06
);
arrow2.position.set(-0.12, 0, 0);
plate2.add(arrow2);

const modeGroup = new THREE.Group();
for (let i = -2; i <= 2; i++) {
  const pts = [
    new THREE.Vector3(-0.55, i * 0.38, 0),
    new THREE.Vector3(0.55, i * 0.38, 0)
  ];
  const geom = new THREE.BufferGeometry().setFromPoints(pts);
  const mat = new THREE.LineBasicMaterial({
    color: 0xffaa00,
    transparent: true,
    opacity: 0.35
  });
  modeGroup.add(new THREE.Line(geom, mat));
}
scene.add(modeGroup);

const particleGeom = new THREE.SphereGeometry(1, 6, 6);
const outsideMat = new THREE.MeshBasicMaterial({
  color: 0x00ffff,
  transparent: true,
  opacity: 0.45,
  blending: THREE.AdditiveBlending,
  depthWrite: false
});
const insideMat = new THREE.MeshBasicMaterial({
  color: 0xffaa00,
  transparent: true,
  opacity: 0.55,
  blending: THREE.AdditiveBlending,
  depthWrite: false
});

const particles = [];

function addParticles(count, xMin, xMax, material, speed, scaleMult) {
  for (let i = 0; i < count; i++) {
    const mesh = new THREE.Mesh(particleGeom, material);
    mesh.position.set(
      xMin + Math.random() * (xMax - xMin),
      -1.1 + Math.random() * 2.2,
      -1.3 + Math.random() * 2.6
    );
    scene.add(mesh);
    particles.push({
      mesh,
      speed,
      phase: Math.random() * Math.PI * 2,
      scaleMult
    });
  }
}

addParticles(90, -3.8, -1.35, outsideMat, 2.4, 1.0);
addParticles(90, 1.35, 3.8, outsideMat, 2.4, 1.0);
addParticles(14, -0.45, 0.45, insideMat, 0.6, 2.8);

const clock = new THREE.Clock();

function animate() {
  const time = clock.getElapsedTime();
  const cycle = Math.sin(time * 1.2) * 0.5 + 0.5;

  const separation = 2.0 - cycle * 0.6;
  plate1.position.x = -separation * 0.5;
  plate2.position.x = separation * 0.5;

  modeGroup.children.forEach((line, idx) => {
    line.material.opacity = 0.2 + 0.2 * Math.sin(time * 3.5 + idx * 1.3);
  });

  particles.forEach(p => {
    const t = p.phase + time * p.speed;
    const pulse = Math.sin(t) * 0.5 + 0.5;
    const s = 0.015 + pulse * 0.035 * p.scaleMult;
    p.mesh.scale.setScalar(s);
  });

  gapLight.intensity = 0.7 + 0.4 * Math.sin(time * 5);

  camera.position.x = Math.sin(time * 0.35) * 0.4;
  camera.position.y = 0.6 + Math.cos(time * 0.25) * 0.25;
  camera.lookAt(0, 0, 0);

  renderer.render(scene, camera);
}

renderer.setAnimationLoop(animate);

